clipboardHistory.value:
general {
    # Ne használj $HOME változót, írd ki a teljes elérési utat vagy használd a ~ jelet
    after_sleep_cmd = pkill -f "hypridle -c /home/FELHASZNÁLÓNEVED/.config/hypr/screenoff.conf"
}

listener {
    timeout = 1
    on-timeout = hyprctl dispatch dpms off && brightnessctl -d *kbd_backlight* set 0
    # Amint megmozdítod az egeret, visszakapcsol és lelövi ezt a példányt
    on-resume = hyprctl dispatch dpms on && brightnessctl -d *kbd_backlight* set 100 && pkill -f "hypridle -c /home/FELHASZNÁLÓNEVED/.config/hypr/screenoff.conf"
}

general {
    # Ha a gép elmegy aludni, ez biztosan leállítja a plusz hypridle-t
    after_sleep_cmd = pkill -f "hypridle --config $HOME/.config/hypr/screenoff.conf"
}

listener {
    timeout = 1
    # Kikapcsolás 0  másodperc után
    on-timeout = hyprctl dispatch dpms off && brightnessctl -d *kbd_backlight* set 0
    # Ébredés bármire
    on-resume = hyprctl dispatch dpms on && brightnessctl -d *kbd_backlight* set 100 && pkill -f "hypridle --config $HOME/.config/hypr/screenoff.conf"
}

listener {
    timeout = 3153600000  # 100 év másodpercben
    on-timeout = hyprctl dispatch dpms off
}

general {
    # Avoid spawning multiple locks if one is already active.
    lock_cmd = pidof hyprlock || hyprlock
    before_sleep_cmd = loginctl lock-session
    after_sleep_cmd = hyprctl dispatch dpms on
}

general {
    # Ha a gép elmegy aludni, ez biztosan leállítja a plusz hypridle-t
    after_sleep_cmd = pkill -f "hypridle --config $HOME/.config/hypr/screenoff.conf"
}

listener {
    timeout = 1
    # Kikapcsolás 0  másodperc után
    on-timeout = hyprctl dispatch dpms off && brightnessctl -d *kbd_backlight* set 0
    # Ébredés bármire
    on-resume = hyprctl dispatch dpms on && brightnessctl -d *kbd_backlight* set 100 && pkill -f "hypridle --config $HOME/.config/hypr/screenoff.conf"
}

general {
    # Ha a gép elmegy aludni, ez biztosan leállítja a plusz hypridle-t
    after_sleep_cmd = pkill -f "hypridle --config $HOME/.config/hypr/screenoff.conf"
}

listener {
    timeout = 2
