    # Ébredés bármire
    on-resume = hyprctl dispatch dpms on && brightnessctl -d *kbd_backlight* set 100 && pkill -f "hypridle --config $HOME/.config/hypr/screenoff.conf"
}

general {
    after_sleep_cmd = pkill -f "hypridle --config ~/.config/hypr/screenoff.conf"
}

listener {
    timeout = 0
    on-timeout = hyprctl dispatch dpms off && brightnessctl -d *kbd_backlight* set 0
        on-resume = hyprctl dispatch dpms on && brightnessctl -d *kbd_backlight* set 100 && pkill -f "hypridle --config ~/.config/hypr/screenoff.conf"
}

general {
    # Amint bármilyen aktivitást észlel, a hypridle leállítja ezt a példányt
    after_sleep_cmd = pkill -f "hypridle --config ~/.config/hypr/screenoff.conf"
}

listener {
    timeout = 0
    # Képernyő KI és Billentyűzet fényerő 0
    on-timeout = hyprctl dispatch dpms off && brightnessctl -d *kbd_backlight* set 0

    # Amint megmozdulsz: Képernyő BE, Billentyűzet vissza (pl. 100-as értékre), és kilépés
    on-resume = hyprctl dispatch dpms on && brightnessctl -d *kbd_backlight* set 100 && pkill -f "hypridle --config ~/.config/hypr/screenoff.conf"
}

general {
    lock_cmd = notify-send "Screen off"
    before_sleep_cmd = loginctl lock-session
    after_sleep_cmd = hyprctl dispatch dpms on
}

listener {
    timeout = 0
     on-timeout = hyprctl dispatch dpms off && brightnessctl -d *kbd_backlight* set 0
    on-resume = hyprctl dispatch dpms on && pkill -f "hypridle --config ~/.config/hypr/screenoff.conf"
}

general {
    lock_cmd = notify-send "Screen off"          # Opcionális
    before_sleep_cmd = loginctl lock-session
    after_sleep_cmd = hyprctl dispatch dpms on   # Biztonsági mentés: ébredéskor kapcsoljon be
}

listener {
    timeout = 0
    # Amint elindul, kikapcsolja a monitort és a billentyűzet világítást
    on-timeout = hyprctl dispatch dpms off && brightnessctl -d *kbd_backlight* set 0
    # Amint megmozdítod az egeret vagy leütsz bármit, visszakapcsol és bezárja a programot
    on-resume = hyprctl dispatch dpms on && pkill -f "hypridle --config ~/.config/hypr/screenoff.conf"
}

